from pathlib import Path
import csv

rows = csv.DictReader((Path(__file__).parent / "inspection.csv").open(encoding="utf-8", newline=""))
totals = {}
for row in rows:
    station = row["station"]
    totals[station] = totals.get(station, 0) + int(row["units"])
print("station,accepted_units")
for station in sorted(totals):
    print(f"{station},{totals[station]}")
